@import "@fontsource-variable/hanken-grotesk";
@import "@fontsource-variable/inter";

/* Light sibling: Anchorage's own paper grey (#f4f5f5) as the page, white panels, black
   text, the same cobalt (#5580f6) and lilac (#ac96ff). */
:root {
  --background: oklch(0.969 0.001 197);
  --foreground: oklch(0 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0 0 0);
  --primary: oklch(0.63 0.183 266);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.922 0.003 265);
  --secondary-foreground: oklch(0 0 0);
  --muted: oklch(1 0 0);
  --muted-foreground: oklch(0.431 0.009 268);
  --accent: oklch(0 0 0 / 6%);
  --accent-foreground: oklch(0 0 0);
  --destructive: oklch(0.562 0.211 24);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.842 0.004 271);
  --input: oklch(0.573 0.011 273);
  --ring: oklch(0.63 0.183 266);
  --highlight: oklch(0.62 0.17 292);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.754 0.116 268);
  --chart-1: oklch(0.63 0.183 266);
  --chart-2: oklch(0.62 0.14 154);
  --chart-3: oklch(0.62 0.17 292);
  --chart-4: oklch(0.475 0.136 266);
  --chart-5: oklch(0.431 0.009 268);
  --sidebar: oklch(1 0 0);
  --sidebar-foreground: oklch(0 0 0);
  --sidebar-primary: oklch(0.63 0.183 266);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.922 0.003 265);
  --sidebar-accent-foreground: oklch(0 0 0);
  --sidebar-border: oklch(0.842 0.004 271);
  --sidebar-ring: oklch(0.63 0.183 266);

  --typeface-body: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Hanken Grotesk Variable", "Inter Variable", ui-sans-serif, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.5rem;
  --page-width: 71.25rem;
  --page-gutter: 1rem;
  --section-y: 8rem;
}

/* Faithful mode: black page (#000), white text, charcoal panels (#313235 fading to black),
   the contact surface #141415 with fields at white 8%, grey text #a2a4a9, hairlines
   #4b4b4d, cobalt #5580f6, lilac #ac96ff, a deep blue glow. */
.dark {
  --background: oklch(0 0 0);
  --foreground: oklch(1 0 0);
  --card: oklch(0.317 0.005 271);
  --card-foreground: oklch(1 0 0);
  --popover: oklch(0.192 0.002 286);
  --popover-foreground: oklch(1 0 0);
  --primary: oklch(0.63 0.183 266);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.192 0.002 286);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.269 0.002 286);
  --muted-foreground: oklch(0.719 0.008 269);
  --accent: oklch(1 0 0 / 10%);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.562 0.211 24);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.414 0.003 286);
  --input: oklch(0.573 0.011 273);
  --ring: oklch(0.63 0.183 266);
  --highlight: oklch(0.735 0.15 292);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.521 0.193 269);
  --chart-1: oklch(0.63 0.183 266);
  --chart-2: oklch(0.792 0.121 154);
  --chart-3: oklch(0.735 0.15 292);
  --chart-4: oklch(0.754 0.116 268);
  --chart-5: oklch(0.719 0.008 269);
  --sidebar: oklch(0.192 0.002 286);
  --sidebar-foreground: oklch(1 0 0);
  --sidebar-primary: oklch(0.63 0.183 266);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.269 0.002 286);
  --sidebar-accent-foreground: oklch(1 0 0);
  --sidebar-border: oklch(0.414 0.003 286);
  --sidebar-ring: oklch(0.63 0.183 266);
}
